import { Button } from '@refy-design/web';
import { Modal } from '@refy-design/web';
import { useState } from 'react';
export function Example() {
  const [open, setOpen] = useState(false);
  return (
    <>
      <Button onClick={() => setOpen(true)}>Open terms</Button>
      <Modal
        open={open}
        onClose={() => setOpen(false)}
        title="Operation terms"
        footer={<Button onClick={() => setOpen(false)}>Got it</Button>}
      >
        {Array.from({ length: 12 }, (_, index) => (
          <p key={index}>
            Clause {index + 1}: the information stays available for review before
            confirmation.
          </p>
        ))}
      </Modal>
    </>
  );
}
